1	export type Item = {
2	  type: string;
3	  material: string;
4	  enchantment: number;
5	  cursed: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type StepResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResult = {
23	  results: StepResult[];
24	};
25	
26	const BASE_PRICES: Record<string, number> = {
27	  sword: 100,
28	  amulet: 60,
29	  staff: 80,
30	  potion: 40,
31	  rune: 25,
32	  moonstone: 25,
33	};
34	
35	// Expressed as integer percent rather than a 1.1 factor: floating-point
36	// multiplication by 1.1 loses exactness (100 * 1.1 === 115.00000000000001),
37	// while scaling by 110 and dividing by 100 stays exact for these prices.
38	const FIRST_CONTRACT_PERCENT = 110;
39	const PERCENT = 100;
40	const CONTRACT_FEE = 5;
41	
42	const basePriceOf = (item: Item): number => BASE_PRICES[item.type];
43	
44	const applyPercent = (amount: number, percent: number): number =>
45	  (amount * percent) / PERCENT;
46	
47	const BLOCK_SIZE = 3;
48	const BLOCK_PRICE = 60;
49	
50	const allAlike = (items: Item[]): boolean =>
51	  items.every((item) => item.type === items[0].type);
52	
53	const sumOfBasePrices = (items: Item[]): number =>
54	  items.reduce((total, item) => total + basePriceOf(item), 0);
55	
56	// Every group of BLOCK_SIZE alike components is priced as one discounted
57	// building block; leftovers keep their individual price.
58	const blockedPriceOf = (items: Item[]): number => {
59	  const blocks = Math.floor(items.length / BLOCK_SIZE);
60	  const leftovers = items.slice(blocks * BLOCK_SIZE);
61	  return blocks * BLOCK_PRICE + sumOfBasePrices(leftovers);
62	};
63	
64	const itemsPriceOf = (items: Item[]): number =>
65	  allAlike(items) ? blockedPriceOf(items) : sumOfBasePrices(items);
66	
67	// Premiums are always rounded up — rounding in MHPCO's favour, per spec.
68	const premiumFor = (itemsPrice: number): number =>
69	  Math.ceil(applyPercent(itemsPrice, FIRST_CONTRACT_PERCENT) + CONTRACT_FEE);
70	
71	const quote = (step: Step): StepResult => ({
72	  premium: premiumFor(itemsPriceOf(step.items)),
73	});
74	
75	export const run = (scenario: Scenario): ScenarioResult => ({
76	  results: [quote(scenario.steps[0])],
77	});
